import{_ as i,C as s,o as l,c as d,j as a,a as t,G as n,aj as r}from"./chunks/framework.BwH0p-pt.js";const y=JSON.parse('{"title":"Admin Essentials","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/admin-essentials.md","filePath":"3.0/introduction/admin-essentials.md","lastUpdated":1785836850000}'),g={name:"3.0/introduction/admin-essentials.md"};function h(c,e,u,p,m,f){const o=s("ImagePopup");return l(),d("div",null,[e[0]||(e[0]=a("h1",{id:"admin-essentials",tabindex:"-1"},[t("Admin Essentials "),a("a",{class:"header-anchor",href:"#admin-essentials","aria-label":'Permalink to "Admin Essentials"'},"​")],-1)),e[1]||(e[1]=a("p",null,"UnoPim 3.0 modernizes the admin panel you work in every day. This page covers the small things you will notice first — themes, navigation, saving, notifications — so nothing surprises you.",-1)),n(o,{src:"/assets/3.0/images/introduction/admin-dark-theme.png",alt:"The admin panel in dark theme"}),e[2]||(e[2]=r('<h2 id="light-and-dark-theme" tabindex="-1">Light and dark theme <a class="header-anchor" href="#light-and-dark-theme" aria-label="Permalink to &quot;Light and dark theme&quot;">​</a></h2><p>The admin now ships with a dark theme alongside the light one.</p><ol><li>Click your profile picture in the top-right corner.</li><li>Choose <strong>Theme: Light</strong>, <strong>Theme: Dark</strong>, or <strong>Theme: Auto</strong>.</li></ol><p>With <strong>Auto</strong> (the default when you have never chosen), the admin follows your browser or operating system preference — switch your computer to dark mode and UnoPim follows. Once you pick Light or Dark, your choice is remembered.</p><h2 id="the-left-navigation" tabindex="-1">The left navigation <a class="header-anchor" href="#the-left-navigation" aria-label="Permalink to &quot;The left navigation&quot;">​</a></h2><p>The sidebar is collapsed by default, showing only icons so your content gets the full width of the screen. Hover over an icon to fly out its submenu.</p><p>Prefer it open? Expand it with the <strong>Collapse/Expand</strong> control at the bottom of the sidebar. UnoPim remembers your choice for the next time you sign in.</p><h2 id="pages-load-without-reloading" tabindex="-1">Pages load without reloading <a class="header-anchor" href="#pages-load-without-reloading" aria-label="Permalink to &quot;Pages load without reloading&quot;">​</a></h2><p>Moving between admin pages no longer reloads the whole browser page. Clicking a menu item or saving a form swaps just the content, so navigation and saves feel instant.</p><p>You lose nothing you are used to: the address bar updates, the browser <strong>Back</strong> and <strong>Forward</strong> buttons work, and you can still bookmark or share any admin page.</p><h2 id="the-save-discard-bar" tabindex="-1">The Save / Discard bar <a class="header-anchor" href="#the-save-discard-bar" aria-label="Permalink to &quot;The Save / Discard bar&quot;">​</a></h2><p>Edit forms no longer have a separate save button in every corner. Instead, one global bar handles saving:</p><ul><li>The bar appears at the top of the page only after you actually change something — it says <strong>You have unsaved changes</strong> and tells you how many sections or fields were modified.</li><li>Changed fields are marked with an <strong>Unsaved</strong> badge, so you can find your own edits at a glance.</li><li><strong>Save changes</strong> saves everything at once.</li><li><strong>Discard</strong> restores every field to its original value. UnoPim asks you to confirm first.</li><li>If you try to leave the page with unsaved changes, UnoPim warns you before anything is lost.</li></ul>',13)),n(o,{src:"/assets/3.0/images/introduction/save-bar.png",alt:"The global Save / Discard bar with unsaved sections"}),e[3]||(e[3]=a("h2",{id:"quick-create-dialogs",tabindex:"-1"},[t("Quick-create dialogs "),a("a",{class:"header-anchor",href:"#quick-create-dialogs","aria-label":'Permalink to "Quick-create dialogs"'},"​")],-1)),e[4]||(e[4]=a("p",null,"You no longer leave your current page to create catalog structure. Attributes, attribute groups, attribute families, category fields, and association types can all be created from a small dialog:",-1)),e[5]||(e[5]=a("ol",null,[a("li",null,[t("Click the "),a("strong",null,"Create"),t(" button on the listing.")]),a("li",null,"Type a name in your catalog language."),a("li",null,"UnoPim generates the code for you — you can edit it before saving."),a("li",null,"Save. The record is created and you can open it for full editing whenever you like.")],-1)),n(o,{src:"/assets/3.0/images/introduction/quick-create-modal.png",alt:"Quick-create dialog with an auto-generated code"}),e[6]||(e[6]=r('<h2 id="toast-notifications" tabindex="-1">Toast notifications <a class="header-anchor" href="#toast-notifications" aria-label="Permalink to &quot;Toast notifications&quot;">​</a></h2><p>Confirmations and errors now appear as small toast messages in the corner of the screen. They confirm a save, report a problem, and disappear on their own — no more messages pushing your page content around.</p><h2 id="signing-in-and-recovering-access" tabindex="-1">Signing in and recovering access <a class="header-anchor" href="#signing-in-and-recovering-access" aria-label="Permalink to &quot;Signing in and recovering access&quot;">​</a></h2><p>The login page was redesigned and gained two practical additions:</p><ul><li><strong>Remember me</strong> — tick it to stay signed in on your own computer.</li><li><strong>Forgot password</strong> — enter your email address to receive a reset link, and set a new password from that email. No administrator needed.</li></ul><h2 id="your-personal-catalog-settings" tabindex="-1">Your personal catalog settings <a class="header-anchor" href="#your-personal-catalog-settings" aria-label="Permalink to &quot;Your personal catalog settings&quot;">​</a></h2><p>Every user now has a personal <strong>Catalog Locale</strong> and <strong>Default Channel</strong>, separate from the interface language. They decide which language and channel UnoPim opens for you when you edit products or browse grids. Set them in <strong>My Account</strong>, or ask your administrator — see <a href="./../settings/users.html">Users</a>.</p><h2 id="profile-pictures-via-gravatar" tabindex="-1">Profile pictures via Gravatar <a class="header-anchor" href="#profile-pictures-via-gravatar" aria-label="Permalink to &quot;Profile pictures via Gravatar&quot;">​</a></h2><p>If you have not uploaded a profile image, UnoPim can show the <a href="https://gravatar.com" target="_blank" rel="noreferrer">Gravatar</a> picture linked to your email address instead. Prefer not to? Untick <strong>Use Gravatar image</strong> in your account settings and UnoPim shows your initials.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All of these preferences — theme, sidebar state, catalog locale, default channel — are per user. Your choices never affect your colleagues.</p></div>',10))])}const b=i(g,[["render",h]]);export{y as __pageData,b as default};
